ACMsg.MPY_NEOPIXEL_NEOPIXEL = "Clase para controlar una tira NeoPixel (WS2812). Crea una instancia con <b>pin</b>, <b>n</b> LEDs y <b>bpp</b> bytes por píxel (por defecto <b>3</b>, o <b>4</b> para RGBW). Devuelve: <b>NeoPixel</b>.";
ACMsg.MPY_NEOPIXEL_NEOPIXEL_INDEX = "Acceso por índice: obtener/establecer un píxel con <b>strip[i]</b> (p. ej. <b>np[0] = (255, 0, 0)</b>).";
ACMsg.MPY_NEOPIXEL_ORDER = "Constante que define el orden de canales de color (p. ej. RGB/GRB) usado por algunos NeoPixels. Devuelve: <b>int</b>.";
ACMsg.MPY_NEOPIXEL_INIT = "Crea una tira NeoPixel en <b>pin</b> con <b>n</b> LEDs. <b>bpp</b> son bytes por píxel (por defecto <b>3</b> para RGB, <b>4</b> para RGBW). Devuelve: <b>NeoPixel</b>.";
ACMsg.MPY_NEOPIXEL_CLEAR = "Apaga todos los LEDs (rellena el búfer con 0). Llama a <b>show()</b> o <b>write()</b> para que el cambio sea visible.";
